{"s6_c01_describes_the_truck_024","any",2,"reg=elite|tmp=veteran|mood=calm|world=vehicle,water,road",{1,"Ham in Riverside says he saw soldiers on the river road - Describes our truck down to the dent",2,"Can we reach him?",1,"We can reach his house",2,"No, move the truck"}},
{"s6_c01_room_for_two_025","any",2,"reg=elite|tmp=veteran|day=6,999|mood=warm",{1,"I keep thinking about the last time Raven Two checked in",2,"Whole team?",1,"Two of them. Asking if we had room",2,"I remember being glad we could say yes that time"}},
{"s6_c01_say_again_026","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Quit saying 'repeat' on the net",2,"Nobody's on the net but us",1,"Then we'll be the last two people alive doing it right"}},
{"s6_c01_tone_still_running_027","any",2,"reg=elite|tmp=veteran|day=3,999|mood=grim",{1,"AM station out of Louisville is still running the alert tone",2,"Nobody left to switch it off",1,"Somebody set it to run, last decision anybody made in that building"}},
{"s6_c01_in_the_clear_028","any",2,"reg=elite|role=elite_operator|tmp=veteran|day=7,999|mood=sad",{1,"Captain wants to transmit in the clear",2,"Captain wants to go home",1,"Same request, the way he said it"}},
{"s6_c01_two_minutes_029","any",2,"reg=elite|tmp=veteran|mood=funny|world=window,building",{1,"Window's in two minutes",2,"I've got nine of them coming up the driveway",1,"Then you've got two minutes and nine of them"}},
{"s6_c01_humming_030","any",3,"reg=elite|tmp=veteran|hour=20,5|mood=funny|world=water",{1,"Who's humming?",2,"Nobody",3,"Nobody's been humming the same four notes since the creek",1,"Nobody stop"}},
{"s6_c01_oak_winning_031","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Throw the long wire over that oak",2,"Third throw, the oak doesn't want it",1,"The oak isn't in charge",2,"The oak is up two to nothing"}},
{"s6_c01_boat_late_032","any",2,"reg=elite|role=mercenary|tmp=veteran|day=6,999|mood=grim",{1,"Client promised a boat at the Brandenburg ramp on the tenth",2,"It's the fourteenth",1,"So either the boat's late or the promise was"}},
{"s6_c01_heavy_lift_north_033","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Rotors - north - heavy lift",2,"Inbound?",1,"Outbound, loaded, from the sound of it"}},
{"s6_c01_inside_cover_034","any",2,"reg=elite|tmp=veteran|day=10,999|mood=sad",{1,"Commo log's full - every page",2,"Use the inside cover",1,"Inside cover's got Doyle's handwriting on it",2,"Back cover, then"}},
{"s6_c01_any_station_035","any",1,"reg=elite|tmp=veteran|day=7,999|hour=0,4|mood=sad",{1,"Any station this net, this is {callsign}",1,"Any station",1,"Any station at all, over"}},
{"s6_c01_still_warm_036","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Pulled a handset off a Guard corporal on 31W",2,"Alive?",1,"The handset works"}},
{"s6_c01_noaa_robot_037","any",2,"reg=elite|tmp=veteran|day=2,999|hour=4,11|mood=funny",{1,"Weather radio's still up, the robot voice",2,"What's it say?",1,"Heat advisory for Hardin and Meade - drink fluids and check on elderly neighbors",2,"Good advice",1,"Checked on one this morning, it went badly"}},
{"s6_c01_fill_expired_038","any",2,"reg=elite|tmp=veteran|day=12,999|hour=20,5|mood=angry",{1,"Crypto fill expired at midnight",2,"Meaning?",1,"Meaning our sets don't talk to anybody's sets until a man with a key drives one out from Bragg",2,"Plain voice, then",1,"Plain voice - like farmers"}},
{"s6_c01_compliant_039","any",2,"reg=elite|tmp=veteran|day=8,999|mood=funny",{1,"Message came through dated last Thursday",2,"Took a week?",1,"Relayed four times, says hold in place and await further instructions",2,"We've been doing that since Thursday",1,"Then we're compliant, somebody write that down"}},
{"s6_c01_wake_me_040","any",2,"reg=elite|role=elite_delta|tmp=veteran|hour=1,4|mood=calm|world=window",{1,"Time",2,"0214",1,"Window",2,"Closed",1,"Next",2,"0600",1,"Wake me at 0555"}},
{"s6_c01_where_army_thin_041","any",2,"reg=elite|tmp=veteran|mood=angry",{1,"Some private on the cordon net is reading the checkpoints off in plain English",2,"Every post?",1,"Every post, with headcounts, anybody with a scanner knows where the wire is thin",2,"Write it down - we're anybody"}},
{"s6_c01_doesnt_fit_pad_042","any",2,"reg=elite|tmp=veteran|hour=17,20|mood=sad|world=window",{1,"Window's at 1900 - anything to send?",2,"Nothing tactical",1,"Something else?",2,"Karen's birthday is Tuesday, doesn't fit on a pad"}},
{"s6_c01_keyed_released_043","any",2,"reg=elite|tmp=veteran|day=5,999|hour=22,4|mood=grim",{1,"Hotel Four's radio keyed twice last night - nobody talked",2,"Stuck mic?",1,"Keyed, released - keyed, released, like a hand that doesn't know what the button does",2,"Turn that channel off"}},
{"s6_c01_package_warm_044","any",2,"reg=elite|tmp=veteran|day=3,999|mood=grim|world=vehicle",{1,"Package status",2,"In the cooler, in the truck",1,"Ice?",2,"Ice went Saturday, the package is warm",1,"Nobody told us what warm does to it"}},
{"s6_c01_boxes_made_flight_045","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=grim",{1,"Brief said escort two scientists and their boxes to the Louisville airport",2,"Where are the scientists?",1,"One's in the truck, one's in Louisville",2,"And the boxes?",1,"The boxes made the flight"}},
{"s6_c01_mirror_black_hawk_046","any",2,"reg=elite|tmp=veteran|hour=8,18|mood=grim",{1,"Flashed the mirror at a Black Hawk over Ekron",2,"It turn?",1,"It turned - Hovered, thought about it - turned back"}},
{"s6_c01_freq_recital_047","any",1,"reg=elite|tmp=veteran|hour=22,5|mood=calm",{1,"Thirty-four fifty - forty-one twenty-five - sixty-two ten",1,"Somebody is up on one of them",1,"Has to be somebody - thirty-four fifty"}},
{"s6_c01_his_lunch_048","any",3,"reg=elite|tmp=veteran|mood=funny",{1,"Who keyed up and didn't talk?",2,"Sat on it",3,"Sat on it for forty seconds, we all heard about the peanut butter crackers",2,"They were good crackers"}},
{"s6_c01_three_letters_049","any",2,"reg=elite|tmp=veteran|day=2,999|mood=calm",{1,"Once heard Morse on the low band, same three letters over and over",2,"SOS?",1,"No. Sounded like somebody's initials. Never found out whose"}},
{"s6_c01_wrong_twenty_050","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"CB kid wants my twenty",2,"Give him a twenty",1,"Gave him the Fort Knox gate, told him to ask for the colonel"}},
{"s6_c01_after_action_051","any",2,"reg=elite|tmp=veteran|day=14,999|mood=grim",{1,"Who's writing the after-action?",2,"For who?",1,"For whoever finds the notebook"}},
{"s6_c01_no_net_traffic_052","any",2,"reg=elite|tmp=veteran|day=20,999|mood=calm",{1,"Anything on the net?",2,"I stopped setting up the antenna Thursday",1,"I noticed, I didn't say anything Thursday either"}},
{"s6_c01_battery_math_053","any",3,"reg=elite|tmp=veteran|day=10,999|hour=16,5|mood=calm|world=window",{1,"We can run the radio or the goggles - not both",2,"Goggles, the radio doesn't keep anybody alive",3,"The radio's the only way anybody knows we're alive",1,"Goggles tonight, radio at the 0600 window, then we argue again"}},
{"s6_c01_lieutenant_colonel_054","any",2,"reg=elite|tmp=veteran|day=2,10|mood=angry",{1,"Some lieutenant colonel on the cordon net demanded to know our unit",2,"You told him?",1,"Told him to call Bragg, he said the phones are down - I said I know"}},
{"s6_c01_closing_log_055","any",1,"reg=elite|tmp=veteran|hour=21,1|mood=grim|world=window",{1,"Window at 2100 - no contact",1,"Window at 2130 - no contact",1,"Writing it neat, somebody's going to read this and I want it neat"}},
{"s6_c02_three_decades_001","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Six men at the feed store - Camouflage from three different decades",2,"Weapons?",1,"Deer rifles, one of them has his scope on upside down",2,"Leave them - Nature's working on it"}},
{"s6_c02_with_the_county_002","any",2,"reg=elite|tmp=veteran|day=0,10|mood=funny",{1,"Deputy at the Ekron crossroads wanted to see identification",2,"And?",1,"Told him we were with the county, he wrote it down on his hand"}},
{"s6_c02_stop_sign_003","any",2,"reg=elite|tmp=veteran|mood=grim|world=vehicle",{1,"Raider in the bed of a pickup on 31W dumped a whole magazine at a stop sign",2,"He hit it?",1,"Sign's fine, everything inside the tire shop came out to see who was knocking"}},
{"s6_c02_saluted_mailbox_004","any",2,"reg=elite|tmp=veteran|day=2,999|mood=funny|world=building",{1,"Guard kid on the barrier hasn't slept in three days",2,"How can you tell from up here?",1,"He just saluted a mailbox"}},
{"s6_c02_car_horn_005","any",3,"reg=elite|tmp=veteran|mood=grim|world=vehicle,road",{1,"Family on {street} is leaning on a car horn for help",2,"How long?",1,"Twenty minutes - help showed up - wrong kind",3,"There were kids in that car",1,"I know what was in the car, mark the street - we don't go"}},
{"s6_c02_trespassers_006","any",2,"reg=elite|tmp=veteran|day=4,999|mood=grim|world=road",{1,"Compound off the Rosewood road - hand-painted signs - Trespassers will be shot",2,"Will they?",1,"Signs are still up, the man who painted them is hung up on his own fence"}},
{"s6_c02_quarry_party_007","any",2,"reg=elite|tmp=veteran|hour=19,3|mood=grim|world=fire,road",{1,"Raiders at the quarry lit a bonfire - music going",2,"Signal fire?",1,"Party, about two hundred guests coming down off the highway now - none of them invited"}},
{"s6_c02_back_door_008","any",2,"reg=elite|tmp=veteran|mood=calm|world=door",{1,"Church in March Ridge, forty people, one entrance",2,"That's a box with a lid",1,"Told the preacher so, he said the Lord is his shield",2,"And?",1,"I said the Lord would still want a back door"}},
{"s6_c02_knocked_first_009","any",2,"reg=elite|tmp=veteran|mood=funny|world=road",{1,"County SWAT is holding the school in Rosewood",2,"Any good?",1,"Good gear, watched them take a house - they knocked and announced",2,"Habit",1,"The whole street came to see who it was"}},
{"s6_c02_on_safe_010","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=angry",{1,"Your Army trains a boy sixteen weeks and gives him a rifle",2,"And?",1,"And the boy at the cordon had it on safe when they came over the wire - I watched through the glass - sixteen weeks"}},
{"s6_c02_cinderblock_011","any",2,"reg=elite|tmp=veteran|mood=grim|world=window",{1,"Couple in a station wagon put a cinderblock through the pharmacy window - noon",2,"Alarm?",1,"Alarm's on battery, they came out with cough syrup and a crowd",2,"They make the wagon?",1,"She did"}},
{"s6_c02_hand_me_her_boy_012","any",2,"reg=elite|tmp=veteran|day=5,999|mood=sad",{1,"Woman at the Brandenburg boat ramp tried to hand me her boy",2,"What'd you do?",1,"Told her where the church group was camped",2,"Church group's gone - since Monday",1,"I know that now"}},
{"s6_c02_jerry_can_013","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Two Guard deserters at the Ekron junction - Trading a rifle and three mags for a can of gas",2,"Who bought?",1,"Farmer, the deserters left thinking they'd robbed him"}},
{"s6_c02_straight_pipes_014","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Bikers on 31W, you can hear them from Muldraugh",2,"So can everything else in Muldraugh",1,"Straight pipes at the end of the world, you have to respect the commitment"}},
{"s6_c02_lighthouse_015","any",2,"reg=elite|tmp=veteran|hour=18,23|mood=funny",{1,"Man with a rifle on top of the water tower",2,"Shooter?",1,"Standing against the sky, smoking, he's a lighthouse",2,"Leave him, he's warning everybody about himself"}},
{"s6_c02_baseball_card_016","any",2,"reg=elite|tmp=veteran|mood=sad",{1,"Local boy followed us two miles, wants to join",2,"Age?",1,"Says nineteen, there's a baseball card clipped in his bicycle spokes",2,"Send him home",1,"Asked him where home was, he pointed at the smoke"}},
{"s6_c02_straight_line_017","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=funny",{1,"Other team's set up at the distillery",2,"Which team?",1,"The one that parks their trucks in a neat straight line",2,"Big Army with longer hair"}},
{"s6_c02_paid_to_018","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=angry",{1,"Green Berets out by Otter Creek won't coordinate",2,"Reason?",1,"They don't work with contractors",2,"Tell them we don't work with anybody who isn't paying - everybody's happy"}},
{"s6_c02_four_wheeler_019","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Some idiot on a four-wheeler, straight down the middle of Rosewood",2,"Where's he going?",1,"Doesn't matter, he's bringing the town with him",2,"Which way?",1,"Ours"}},
{"s6_c02_keys_in_it_020","any",2,"reg=elite|tmp=veteran|mood=funny|world=vehicle",{1,"Locals parked a school bus across the Riverside bridge",2,"Smart",1,"Smart, then they left the keys in it"}},
{"s6_c02_irvington_four_021","any",2,"reg=elite|tmp=veteran|day=6,999|mood=sad|world=vehicle,door",{1,"Volunteer fire department in Irvington held their station a week - four of them",2,"How?",1,"Pumper truck across the bay doors - axes",2,"They still there?",1,"Truck's still there"}},
{"s6_c02_sweet_tea_022","any",2,"reg=elite|tmp=veteran|hour=10,18|mood=warm|world=road",{1,"Old man on the farm road brought out a pitcher of sweet tea",2,"You drank it?",1,"He stood there and watched me drink it, wouldn't take anything for it",2,"Tell him to get out of here",1,"He's eighty-one, says he's done leaving places"}},
{"s6_c02_water_tower_paint_023","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Gang in West Point spray-painted their name on the water tower",2,"Marking territory",1,"Marking the address"}},
{"s6_c02_both_legs_024","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Raiders set an ambush on the Fallas Lake bend",2,"How'd they lay it out?",1,"L-shaped - nearly, the two legs of the L are shooting at each other",2,"Give it an hour, they'll do our job for us"}},
{"s6_c02_more_than_they_need_025","any",2,"reg=elite|tmp=veteran|day=10,999|mood=grim",{1,"Farmhouse on the ridge, family of five - a dog",2,"Supplies?",1,"More than they need",2,"We're not doing that",1,"I didn't say we were, I said more than they need"}},
{"s6_c02_bullhorn_colonel_026","any",2,"reg=elite|tmp=veteran|day=1,8|mood=funny",{1,"Colonel at the cordon is giving a statement into a bullhorn",2,"To what press?",1,"There isn't any, I think he's rehearsing"}},
{"s6_c02_orange_jumpsuits_027","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Orange jumpsuits walking the rail line",2,"Count?",1,"Eleven - ten, one stopped to tie his shoe"}},
{"s6_c02_commonwealth_028","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"State trooper tried to commandeer our truck",2,"On whose authority?",1,"The Commonwealth of Kentucky, he was very sure about it",2,"Where is he now?",1,"Walking, he took the Commonwealth with him"}},
{"s6_c02_org_chart_029","any",2,"reg=elite|tmp=veteran|mood=funny|world=building",{1,"Man on a porch in Ekron put two rounds over our heads",2,"Why?",1,"Hollered that the Army did this",2,"We're not the Army",1,"Didn't seem the moment to walk him through the org chart"}},
{"s6_c02_buses_coming_030","any",2,"reg=elite|tmp=veteran|day=3,999|mood=sad|world=cars",{1,"Lady in Rosewood saw the uniforms and started crying, asked where the buses were",2,"What'd you tell her?",1,"Coming",2,"Nobody authorized you to say that",1,"Nobody's authorized anything since Friday"}},
{"s6_c02_counted_shotguns_031","any",2,"reg=elite|tmp=veteran|day=8,999|mood=funny",{1,"Raider boss on nineteen says he's the new sheriff of the county",2,"Elected?",1,"Says there was a vote, they counted shotguns"}},
{"s6_c02_squirrel_gun_032","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"Somebody's working a twenty-two from the Baptist steeple",2,"Hitting?",1,"Every round, one at a time - no hurry in it",2,"Who?",1,"Lady in her seventies with a squirrel gun, I'd take her over half of Bragg"}},
{"s6_c02_toll_road_033","any",2,"reg=elite|tmp=veteran|day=6,999|mood=calm|world=road",{1,"Militia on the Brandenburg road is charging a toll, cigarettes, gas, ammunition",2,"They charge us?",1,"They looked at us and waved, the toll's only for people who pay tolls"}},
{"s6_c02_face_paint_034","any",2,"reg=elite|tmp=veteran|mood=warm|world=trees",{1,"Two boys in the treeline - face paint, following us for an hour",2,"How close?",1,"Close enough to hear them giggle",2,"Better fieldcraft than most raiders I've seen"}},
{"s6_c02_horse_thread_035","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"Vet in March Ridge sewed up Pruett's arm",2,"A horse vet?",1,"Said an arm is just a short leg - Neatest stitches I've seen outside a real hospital"}},
{"s6_c02_creamed_corn_036","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Raider out front with a T-shirt on a stick, wants to trade for the SAW",2,"Offering what?",1,"A girl's bicycle and eleven cans of creamed corn",2,"Ask him how many cans for the ammunition"}},
{"s6_c02_in_charge_of_chair_037","any",2,"reg=elite|tmp=veteran|day=2,999|mood=funny",{1,"Federal agent in a windbreaker at the motel in Muldraugh - says he's running the investigation",2,"Into what?",1,"Wouldn't say, he's been in room nine since Saturday - chair under the knob",2,"So he's in charge of the chair"}},
{"s6_c02_thirty_hour_shift_038","any",2,"reg=elite|tmp=veteran|mood=grim|world=vehicle",{1,"Cordon opened up on a pickup at the Salt River bridge",2,"Infected?",1,"Wrong turn",2,"Guard?",1,"Guard, nineteen, thirty hours on shift - not their fault, somebody briefed it bad"}},
{"s6_c02_high_and_left_039","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Rounds coming in high and left, every single one",2,"Same shooter?",1,"Same shooter, somebody ought to tell him",2,"Don't you dare"}},
{"s6_c02_tape_in_garage_040","any",2,"reg=elite|tmp=veteran|hour=19,1|mood=grim|world=door,generator",{1,"House on {street} is running a generator in the garage - door up - TV on",2,"TV? There's no signal",1,"They're watching a tape, half the neighborhood's watching it with them from the yard"}},
{"s6_c02_jail_on_foot_041","any",2,"reg=elite|tmp=veteran|day=3,12|mood=sad|world=road",{1,"Deputy walking four prisoners down the road in cuffs",2,"To where?",1,"The jail in Louisville - on foot",2,"He doesn't know about Louisville?",1,"I didn't tell him, didn't have it in me - that's new"}},
{"s6_c02_come_back_to_car_042","any",2,"reg=elite|tmp=veteran|mood=funny|world=vehicle",{1,"Gang kids in West Point on toy walkie-talkies, using callsigns",2,"Such as?",1,"Big Money - Reaper, and one who keeps asking Reaper to come back to the car"}},
{"s6_c02_anybody_in_here_043","any",2,"reg=elite|tmp=veteran|mood=grim|world=door,inside",{1,"Watched a man clear a house by yelling 'anybody in here?' from the doorway",2,"Anybody answer?",1,"Everybody answered"}},
{"s6_c02_chainsaw_044","any",3,"reg=elite|tmp=veteran|mood=funny",{1,"Local fella in overalls took on six of them with a chainsaw",2,"How'd that go?",1,"Great for about fifteen seconds",3,"And then?",1,"Then the chain came off and he found out he's a runner"}},
{"s6_c02_raider_flag_045","any",2,"reg=elite|tmp=veteran|mood=calm|world=vehicle,wind",{1,"Raiders flying a flag over the truck stop, skull on a bedsheet",2,"Morale",1,"Range marker, it's four hundred meters from the ridge and it tells me the wind"}},
{"s6_c02_old_timer_rifle_046","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"Old man in the hardware store asked what unit",2,"You tell him?",1,"No, he told me his - Korea, then he sold me nails at the old price and saluted"}},
{"s6_c02_hunting_blind_047","any",2,"reg=elite|tmp=veteran|mood=grim|world=trees,road",{1,"Hunter up in a tree stand on the Ekron road - been there two days",2,"Waiting for them to pass?",1,"They're sitting under the tree, he's waiting for them to get bored",2,"They don't get bored"}},
{"s6_c02_prayer_meeting_048","any",3,"reg=elite|tmp=veteran|day=4,999|hour=16,5|mood=calm",{1,"Family in the brick house asked us in for supper",2,"No",3,"They've got a garden - green beans",2,"They'll want us to stay",1,"Supper - not staying, we eat and we're gone before dark"}},
{"s6_c02_police_tape_049","any",2,"reg=elite|tmp=veteran|day=0,4|mood=funny",{1,"Cops strung crime scene tape around the whole Muldraugh post office",2,"Doing its job?",1,"Two of them are wrapped up in it at the corner - so partly"}},
{"s6_c02_raider_rifle_care_050","any",2,"reg=elite|role=elite_delta|tmp=veteran|mood=angry",{1,"Took an M16 off the raider at the bridge",2,"Condition?",1,"Rust in the chamber and a Bible verse in marker on the stock - he trusted the verse"}},
{"s6_c02_hitchhiker_051","any",2,"reg=elite|tmp=veteran|day=2,999|mood=grim",{1,"Hitchhiker at the Rosewood turnoff - thumb out",2,"Stop?",1,"Look at the arm he's holding against his belly first",2,"Towel",1,"Keep driving"}},
{"s6_c02_bought_ammo_052","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=funny",{1,"Bought a case of ammunition off the militia with a gold watch",2,"Real gold?",1,"Flea market in Juarez, their ammunition is garage reloads - fair market"}},
{"s6_c03_signal_for_dog_001","any",2,"reg=elite|tmp=veteran|mood=funny|world=trees",{1,"Hand signals only until the treeline",2,"What's the hand signal for dog?",1,"There isn't one",2,"There's a dog"}},
{"s6_c03_head_high_corn_002","any",2,"reg=elite|tmp=veteran|day=0,60|mood=calm",{1,"Corn's head high, straight through saves two miles",2,"In there nobody sees us",1,"In there nobody sees anything, we go around"}},
{"s6_c03_three_leaves_003","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Watch the vine - three leaves",2,"Too late, I'm in it to the elbow",1,"Don't scratch, anybody seen scratching out here gets looked at twice"}},
{"s6_c03_chiggers_004","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Chiggers",2,"Where?",1,"Everywhere my belt has been"}},
{"s6_c03_havent_said_stop_005","any",2,"reg=elite|tmp=veteran|hour=11,17|mood=calm",{1,"Your lips are white",2,"I'm fine",1,"Drink until I say stop",2,"Sergeant",1,"I haven't said stop"}},
{"s6_c03_hands_on_glass_006","any",2,"reg=elite|tmp=veteran|hour=20,4|mood=grim|world=vehicle",{1,"Cross 31W one at a time, thirty seconds apart",2,"Third car - hands on the inside of the glass",1,"Then we cross at the fourth car"}},
{"s6_c03_railroad_ties_007","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Follow the rail bed to West Point, walk the ties - Gravel's loud",2,"Ties are spaced for nobody's legs",1,"Then shorten your legs"}},
{"s6_c03_attic_ladder_008","any",2,"reg=elite|tmp=veteran|mood=grim|world=stairs,building",{1,"Four rooms, a closet, an attic",2,"Attic?",1,"Pull-down ladder, scratching up there since we came in",2,"Then it stays an attic, nail the hatch"}},
{"s6_c03_half_drawn_009","any",2,"reg=elite|tmp=veteran|mood=calm|world=window,road",{1,"Hide's the upstairs east window, curtain half drawn",2,"Why half?",1,"Every other house on the street is half drawn, we look like the neighbors"}},
